// bind is bindPreds plus the paging arguments, in suffix order.
func (q Query) bind(b *binder) []any {
	v := q.bindPreds(b)
	b.limit = q.limit
	v = append(v, &b.limit)
	// An offset of zero is absent from the statement, so binding it
	// would leave an argument nothing consumes.
	if q.offset > 0 {
		b.offset = q.offset
		v = append(v, &b.offset)
	}
	b.vals = v
	return v
}

// All runs the query and decodes every row.
func (q Query) All(ctx context.Context, ex runtime.Executor, dst []Row) ([]Row, error) {
	var sl runtime.Slab
	return q.AllInto(ctx, ex, dst, &sl)
}

// AllInto lets the caller own the string arena.
func (q Query) AllInto(ctx context.Context, ex runtime.Executor, dst []Row, sl *runtime.Slab) ([]Row, error) {
	if err := q.Err(); err != nil {
		return dst, err
	}
	var buf [21]runtime.Tok
	st := stmtFor(q.stream(&buf), q.offset > 0, q.lock)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return dst, st.Err
	}
	sl.Reserve(st.SlabHint())
	b := binders.Get()
	defer putBinder(b)

	rows, err := ex.Query(ctx, st.SQL, q.bind(b))
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// One returns the first row, if any.
func (q Query) One(ctx context.Context, ex runtime.Executor) (Row, bool, error) {
	var sl runtime.Slab
	var buf [1]Row
	out, err := q.Limit(1).AllInto(ctx, ex, buf[:0], &sl)
	if err != nil || len(out) == 0 {
		return Row{}, false, err
	}
	return out[0], true, nil
}

// Count ignores Limit: counting a truncated set is a bug, not a feature.
func (q Query) Count(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.Err(); err != nil {
		return 0, err
	}
	if q.lock != 0 {
		return 0, errCountLocked
	}
	var buf [21]runtime.Tok
	st := countStmtFor(q.preds(&buf))
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	// bindPreds, not bind: a count has no LIMIT and no OFFSET. The old
	// form bound everything and sliced the last argument off, which was
	// the limit — unless Offset was set, in which case it silently kept
	// the limit and dropped the offset, and the statement mismatched.
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return 0, err
	}
	defer rows.Close()
	var n int64
	if rows.Next() {
		n = runtime.Int8(rows.RawValues()[0])
	}
	return n, rows.Err()
}

// Exists asks the one-bit question with a one-bit statement: SELECT 1,
// no ORDER BY, LIMIT 1. It was previously One() with the row thrown
// away, which projected every column AND carried the default ordering —
// measured on 50k rows, the planner top-N-sorted all 16,667 matches to
// return the "first" of an order nobody was going to read.
func (q Query) Exists(ctx context.Context, ex runtime.Executor) (bool, error) {
	if err := q.Err(); err != nil {
		return false, err
	}
	if q.lock != 0 {
		return false, errExistsLocked
	}
	var buf [21]runtime.Tok
	st := existsStmtFor(q.preds(&buf))
	if st.Err != nil {
		return false, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	rows, err := ex.Query(ctx, st.SQL, q.bindPreds(b))
	if err != nil {
		return false, err
	}
	defer rows.Close()
	return rows.Next(), rows.Err()
}

// Prepare resolves the structure and binds arguments without executing.
func (q Query) Prepare(b *Binder) (string, []any) {
	var buf [21]runtime.Tok
	return stmtFor(q.stream(&buf), q.offset > 0, q.lock).SQL, q.bind(b)
}

