// DeleteOp is a delete as a queueable statement.
func DeleteOp(iD [16]byte) runtime.BatchOp {
	return runtime.BatchOp{SQL: deleteSQL, Args: []any{iD}}
}

// Table is the table these statements write, so a Unit can order a mixed
// batch by foreign key without knowing what any of them are.
const Table = "batch_operations"

// stmtForKey compiles the UPDATE for one (dirty, expr) pair, once.
//
// The pair is the identity, not the dirty mask alone: the same column
// assigned a bound value and assigned a server-side expression are two
// different statements, and the arguments of one do not fit the other.
//
// ret picks the cache as well as the suffix. The batch path passes
// false — it cannot read rows back, so it must not ask for them.
func stmtForKey(k runtime.MaskKey, ret bool) *runtime.Stmt {
	cache := updCache
	if !ret {
		cache = updOpCache
	}
	if st := cache.Get(k); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		// An expression wins: a column set both ways cannot happen,
		// because each setter clears the other's bit.
		switch {
		case k.Expr&k.Dirty&(1<<uint(i)) != 0:
			set = append(set, addFrags[i])
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	where := make([]runtime.Frag, 0, 2)
	where = append(where, pkFrags[:]...)
	// Only an expression needs reading back. A plain UPDATE already
	// knows every value it wrote, so it pays no RETURNING.
	suffix := ""
	if ret && k.Expr != 0 {
		suffix = updReturning
	}
	return cache.Put(k, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
		{Lead: " WHERE ", Sep: " AND ", Frags: where},
	}, suffix))
}

// Update writes the assigned columns of one row.
//
// Assigning nothing is not an error and issues no statement — an UPDATE
// with an empty SET list is not valid SQL, and a caller looping over
// possibly-changed fields should not have to special-case the empty case.
//
// An assignment the DATABASE computes is read back in the same
// statement, so m.Row() is the row that now exists rather than the
// one that used to. A second SELECT would race every other writer,
// which is the same reason Insert reads its row back.
func (m *Mut) Update(ctx context.Context, ex runtime.Executor) error {
	if m.dirty == 0 && m.expr == 0 {
		return nil
	}
	st := stmtForKey(m.key(), true)
	if st.Err != nil {
		// A malformed token stream is a code-generation bug. Executing it
		// would run a query whose filter is not the one that was asked for.
		return st.Err
	}
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.ProjectID)
		case 2:
			args = append(args, m.row.OrganizationID)
		case 3:
			args = append(args, m.row.Kind)
		case 4:
			args = append(args, m.row.Reason)
		case 5:
			args = append(args, m.row.FilterStatus)
		case 6:
			args = append(args, m.row.FilterDefinitionID.Arg())
		case 7:
			args = append(args, m.row.FilterBusinessKey)
		case 8:
			args = append(args, m.row.FilterNeedsAttention)
		case 9:
			args = append(args, m.row.RequestedBy)
		case 10:
			args = append(args, m.row.RequestedByID)
		case 11:
			args = append(args, m.row.Status)
		case 12:
			args = append(args, m.row.Total)
		case 13:
			args = append(args, m.row.Succeeded)
		case 14:
			args = append(args, m.row.Failed)
		case 15:
			args = append(args, m.row.Skipped)
		case 16:
			args = append(args, m.row.LeaseExpires.Arg())
		case 17:
			args = append(args, m.row.FinishedAt.Arg())
		case 18:
			args = append(args, m.row.StoppedBy)
		case 19:
			args = append(args, m.row.StopReason)
		}
	}
	args = append(args, m.row.ID)
	if m.expr != 0 {
		return m.updateReturning(ctx, ex, st, args)
	}
	n, err := ex.Exec(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

// updateReturning runs an UPDATE that let the database compute part of
// the row, and reads the whole row back into the staged copy.
//
// Every column, not just the computed ones: a trigger may have touched
// anything, and a staged row that is fresh in two fields and stale in
// the rest is harder to reason about than one that is simply current.
func (m *Mut) updateReturning(ctx context.Context, ex runtime.Executor, st *runtime.Stmt, args []any) error {
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return err
	}
	defer rows.Close()
	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return err
		}
		return runtime.ErrNoRow
	}
	// The staged row owns this arena, the way an inserted row does.
	var sl runtime.Slab
	if err := scan(rows.RawValues(), &m.row, &sl); err != nil {
		return err
	}
	if err := rows.Err(); err != nil {
		return err
	}
	m.dirty = 0
	m.expr = 0
	return nil
}

var deleteSQL = runtime.SpliceSections(deletePrefix, []runtime.Section{
	{Lead: " WHERE ", Sep: " AND ", Frags: pkFrags[:]},
}, "").SQL

// Delete removes one row by primary key. A row that was already gone is
// runtime.ErrNoRow, not success: a caller deleting something that is not
// there usually has a bug, and swallowing it hides the bug.
func Delete(ctx context.Context, ex runtime.Executor, iD [16]byte) error {
	n, err := ex.Exec(ctx, deleteSQL, []any{iD})
	if err != nil {
		return err
	}
	if n == 0 {
		return runtime.ErrNoRow
	}
	return nil
}

// Set-based writes. Two caches of their own, keyed like the read
// caches by the predicate stream — UpdateAll's prefixed with the
// assignment masks, which are as much its identity as the predicates.
var (
	updAllCache = runtime.NewTreeCache()
	delAllCache = runtime.NewTreeCache()
)

// writeAllErr is what UpdateAll and DeleteAll refuse.
func (q Query) writeAllErr() error {
	if err := q.Err(); err != nil {
		return err
	}
	if q.nt == 0 {
		return runtime.ErrUnfilteredWrite
	}
	if q.limit != 1000 || q.offset != 0 || q.lock != 0 {
		return runtime.ErrPagedWrite
	}
	return nil
}

// updAllStmtFor compiles one (assignments, predicates) pair, once.
func updAllStmtFor(k runtime.MaskKey, preds []runtime.Tok) *runtime.Stmt {
	return updAllStmtIn(updAllCache, "", k, preds)
}

func updAllStmtIn(c *runtime.TreeCache, suffix string, k runtime.MaskKey, preds []runtime.Tok) *runtime.Stmt {
	var key [25]runtime.Tok
	key[0], key[1] = runtime.Tok(k.Dirty), runtime.Tok(k.Dirty>>32)
	key[2], key[3] = runtime.Tok(k.Expr), runtime.Tok(k.Expr>>32)
	n := 4 + copy(key[4:], preds)
	if st := c.Get(key[:n]); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		switch {
		case k.Expr&k.Dirty&(1<<uint(i)) != 0:
			set = append(set, addFrags[i])
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	head := runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
	}, "")
	if head.Err != nil {
		return head
	}
	return c.Put(key[:n], runtime.SpliceTreeFrom(head.SQL, preds, lowering, suffix, head.NArg))
}

// UpdateAll writes m's assigned columns to every row the query
// matches, in ONE statement, and reports how many it wrote:
//
//	var m Mut
//	m.Set…(v)            // bound values and server-side forms alike
//	n, err := New().Where(…).UpdateAll(ctx, ex, m)
//
// Only assigned columns are written, as for Update; nothing assigned
// issues no statement and reports 0. The query must have a predicate —
// runtime.ErrUnfilteredWrite otherwise — and must not carry Limit,
// Offset or a row lock, which a set-based UPDATE has no clause for:
// runtime.ErrPagedWrite. Order is ignored, as it is by Count.
func (q Query) UpdateAll(ctx context.Context, ex runtime.Executor, m Mut) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	if m.dirty == 0 && m.expr == 0 {
		return 0, nil
	}
	var buf [21]runtime.Tok
	st := updAllStmtFor(m.key(), q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	args := make([]any, 0, st.NArg)
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.ProjectID)
		case 2:
			args = append(args, m.row.OrganizationID)
		case 3:
			args = append(args, m.row.Kind)
		case 4:
			args = append(args, m.row.Reason)
		case 5:
			args = append(args, m.row.FilterStatus)
		case 6:
			args = append(args, m.row.FilterDefinitionID.Arg())
		case 7:
			args = append(args, m.row.FilterBusinessKey)
		case 8:
			args = append(args, m.row.FilterNeedsAttention)
		case 9:
			args = append(args, m.row.RequestedBy)
		case 10:
			args = append(args, m.row.RequestedByID)
		case 11:
			args = append(args, m.row.Status)
		case 12:
			args = append(args, m.row.Total)
		case 13:
			args = append(args, m.row.Succeeded)
		case 14:
			args = append(args, m.row.Failed)
		case 15:
			args = append(args, m.row.Skipped)
		case 16:
			args = append(args, m.row.LeaseExpires.Arg())
		case 17:
			args = append(args, m.row.FinishedAt.Arg())
		case 18:
			args = append(args, m.row.StoppedBy)
		case 19:
			args = append(args, m.row.StopReason)
		}
	}
	args = append(args, q.bindPreds(b)...)
	return ex.Exec(ctx, st.SQL, args)
}

func delAllStmtFor(toks []runtime.Tok) *runtime.Stmt {
	if st := delAllCache.Get(toks); st != nil {
		return st
	}
	return delAllCache.Put(toks, runtime.SpliceTree(deletePrefix, toks, lowering, ""))
}

// DeleteAll removes every row the query matches, in ONE statement,
// and reports how many it removed.
//
// The query must have a predicate — runtime.ErrUnfilteredWrite
// otherwise — and must not carry Limit, Offset or a row lock:
// runtime.ErrPagedWrite. Order is ignored, as it is by Count.
func (q Query) DeleteAll(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	var buf [21]runtime.Tok
	st := delAllStmtFor(q.preds(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	return ex.Exec(ctx, st.SQL, q.bindPreds(b))
}

var takeCache = runtime.NewTreeCache()

// takeOpen narrows the UPDATE to the rows the read selects.
const takeOpen = ` WHERE "id" IN (SELECT "id" FROM "batch_operations"`

var takeHeadCache = runtime.NewMaskCache()

// takeHead is the UPDATE … SET of one assignment mask, before the read
// that narrows it.
func takeHead(k runtime.MaskKey) *runtime.Stmt {
	if st := takeHeadCache.Get(k); st != nil {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		switch {
		case k.Expr&k.Dirty&(1<<uint(i)) != 0:
			set = append(set, addFrags[i])
		case k.Expr&(1<<uint(i)) != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&(1<<uint(i)) != 0:
			set = append(set, setFrags[i])
		}
	}
	return takeHeadCache.Put(k, runtime.SpliceSections(updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
	}, ""))
}

// takeStmtFor compiles one (assignments, lock, read) triple, once.
func takeStmtFor(k runtime.MaskKey, lock uint8, toks []runtime.Tok) *runtime.Stmt {
	var key [26]runtime.Tok
	key[0], key[1] = runtime.Tok(k.Dirty), runtime.Tok(k.Dirty>>32)
	key[2], key[3] = runtime.Tok(k.Expr), runtime.Tok(k.Expr>>32)
	key[4] = runtime.Tok(lock)
	n := 5 + copy(key[5:], toks)
	if st := takeCache.Get(key[:n]); st != nil {
		return st
	}
	head := takeHead(k)
	if head.Err != nil {
		return head
	}
	suffix := limitSuffix + lockSuffix[lock] + `)` + updReturning
	return takeCache.Put(key[:n], runtime.SpliceTreeFrom(head.SQL+takeOpen, toks, lowering, suffix, head.NArg))
}

// Take writes m's assigned columns to the rows the query would read —
// its predicates, order, Limit and row lock all apply — in ONE
// statement, and returns those rows as they now stand:
//
//	var m Mut
//	m.Set…(leaseEnd)
//	got, err := New().Where(…).Order(…).Limit(1).ForUpdateSkipLocked().Take(ctx, ex, m, nil)
//
// That is the queue claim: with ForUpdateSkipLocked two workers asking
// at once take different rows, or one finds none, and neither waits.
// Without a lock it is an UPDATE bounded by a read. Nothing assigned
// issues no statement and returns dst. Offset is refused with
// runtime.ErrPagedWrite: a claim that skips rows it could take is a
// claim that leaves work behind.
func (q Query) Take(ctx context.Context, ex runtime.Executor, m Mut, dst []Row) ([]Row, error) {
	if err := q.Err(); err != nil {
		return dst, err
	}
	if q.offset != 0 {
		return dst, runtime.ErrPagedWrite
	}
	if m.dirty == 0 && m.expr == 0 {
		return dst, nil
	}
	var buf [21]runtime.Tok
	st := takeStmtFor(m.key(), q.lock, q.stream(&buf))
	if st.Err != nil {
		return dst, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	args := append(m.takeArgs(make([]any, 0, st.NArg)), q.bind(b)...)
	var sl runtime.Slab
	sl.Reserve(st.SlabHint())
	rows, err := ex.Query(ctx, st.SQL, args)
	if err != nil {
		return dst, err
	}
	defer rows.Close()
	for rows.Next() {
		dst = append(dst, Row{})
		if err := scan(rows.RawValues(), &dst[len(dst)-1], &sl); err != nil {
			return dst, err
		}
	}
	st.ObserveSlab(sl.Size())
	return dst, rows.Err()
}

// takeArgs appends the values m assigns, in SET order.
func (m Mut) takeArgs(args []any) []any {
	for i := 0; i < nUpdatable; i++ {
		if m.dirty&(1<<uint(i)) == 0 {
			continue
		}
		switch i {
		case 0:
			args = append(args, m.row.UpdatedAt)
		case 1:
			args = append(args, m.row.ProjectID)
		case 2:
			args = append(args, m.row.OrganizationID)
		case 3:
			args = append(args, m.row.Kind)
		case 4:
			args = append(args, m.row.Reason)
		case 5:
			args = append(args, m.row.FilterStatus)
		case 6:
			args = append(args, m.row.FilterDefinitionID.Arg())
		case 7:
			args = append(args, m.row.FilterBusinessKey)
		case 8:
			args = append(args, m.row.FilterNeedsAttention)
		case 9:
			args = append(args, m.row.RequestedBy)
		case 10:
			args = append(args, m.row.RequestedByID)
		case 11:
			args = append(args, m.row.Status)
		case 12:
			args = append(args, m.row.Total)
		case 13:
			args = append(args, m.row.Succeeded)
		case 14:
			args = append(args, m.row.Failed)
		case 15:
			args = append(args, m.row.Skipped)
		case 16:
			args = append(args, m.row.LeaseExpires.Arg())
		case 17:
			args = append(args, m.row.FinishedAt.Arg())
		case 18:
			args = append(args, m.row.StoppedBy)
		case 19:
			args = append(args, m.row.StopReason)
		}
	}
	return args
}

// TakeHead is Take's statement without its read, for the context
// package to narrow with a composed one: the UPDATE … SET, what opens
// and closes the read (the lock q holds spelled in the close), the
// identity a statement built from them is cached under, and the values
// m assigns. ok is false when m assigns nothing.
func (m Mut) TakeHead(q Query) (head *runtime.Stmt, open, close string, key [5]runtime.Tok, args []any, ok bool) {
	if m.dirty == 0 && m.expr == 0 {
		return nil, "", "", key, nil, false
	}
	key[0], key[1] = runtime.Tok(m.dirty), runtime.Tok(m.dirty>>32)
	key[2], key[3] = runtime.Tok(m.expr), runtime.Tok(m.expr>>32)
	key[4] = runtime.Tok(q.lock)
	return takeHead(m.key()), takeOpen, lockSuffix[q.lock] + `)` + updReturning, key, m.takeArgs(nil), true
}

var trimCache = runtime.NewTreeCache()

// trimStmtFor compiles one (lock, read) pair, once.
func trimStmtFor(lock uint8, toks []runtime.Tok) *runtime.Stmt {
	var key [22]runtime.Tok
	key[0] = runtime.Tok(lock)
	n := 1 + copy(key[1:], toks)
	if st := trimCache.Get(key[:n]); st != nil {
		return st
	}
	suffix := limitSuffix + lockSuffix[lock] + `))`
	return trimCache.Put(key[:n], runtime.SpliceTree(deletePrefix+` WHERE ctid = ANY(ARRAY(SELECT ctid FROM "batch_operations"`, toks, lowering, suffix))
}

// DeleteBatch removes the rows the query would read —
// its predicates, order, Limit and row lock all apply — in ONE
// statement, and reports how many it removed:
//
//	for {
//		n, err := New().Where(…).Limit(1000).DeleteBatch(ctx, ex)
//		if err != nil || n < 1000 {
//			break
//		}
//	}
//
// That is the bounded purge: each run holds its locks for one batch.
// The query must have a predicate — runtime.ErrUnfilteredWrite
// otherwise — and Offset is refused with runtime.ErrPagedWrite.
func (q Query) DeleteBatch(ctx context.Context, ex runtime.Executor) (int64, error) {
	if err := q.Err(); err != nil {
		return 0, err
	}
	if q.nt == 0 {
		return 0, runtime.ErrUnfilteredWrite
	}
	if q.offset != 0 {
		return 0, runtime.ErrPagedWrite
	}
	var buf [21]runtime.Tok
	st := trimStmtFor(q.lock, q.stream(&buf))
	if st.Err != nil {
		return 0, st.Err
	}
	b := binders.Get()
	defer putBinder(b)
	return ex.Exec(ctx, st.SQL, q.bind(b))
}

// The step this table's UpdateAll is, and the statements written after
// another table's step.
var updStepCache = runtime.NewTreeCache()

const stepReturning = ` RETURNING "id"`

// UpdateAllStep is UpdateAll as a step: it writes when the statement
// it is handed to runs, and that statement's write can count the rows it
// wrote. It refuses what UpdateAll refuses, and nothing assigned is
// refused with runtime.ErrNothingAssigned: a step that writes nothing
// would count nothing for a reason nobody asked for.
func (q Query) UpdateAllStep(m Mut) runtime.Step {
	return func(run func(string, []any) error) error {
		if err := q.writeAllErr(); err != nil {
			return err
		}
		if m.dirty == 0 && m.expr == 0 {
			return runtime.ErrNothingAssigned
		}
		var buf [21]runtime.Tok
		st := updAllStmtIn(updStepCache, stepReturning, m.key(), q.preds(&buf))
		if st.Err != nil {
			return st.Err
		}
		b := binders.Get()
		defer putBinder(b)
		args := make([]any, 0, st.NArg)
		for i := 0; i < nUpdatable; i++ {
			if m.dirty&(1<<uint(i)) == 0 {
				continue
			}
			switch i {
			case 0:
				args = append(args, m.row.UpdatedAt)
			case 1:
				args = append(args, m.row.ProjectID)
			case 2:
				args = append(args, m.row.OrganizationID)
			case 3:
				args = append(args, m.row.Kind)
			case 4:
				args = append(args, m.row.Reason)
			case 5:
				args = append(args, m.row.FilterStatus)
			case 6:
				args = append(args, m.row.FilterDefinitionID.Arg())
			case 7:
				args = append(args, m.row.FilterBusinessKey)
			case 8:
				args = append(args, m.row.FilterNeedsAttention)
			case 9:
				args = append(args, m.row.RequestedBy)
			case 10:
				args = append(args, m.row.RequestedByID)
			case 11:
				args = append(args, m.row.Status)
			case 12:
				args = append(args, m.row.Total)
			case 13:
				args = append(args, m.row.Succeeded)
			case 14:
				args = append(args, m.row.Failed)
			case 15:
				args = append(args, m.row.Skipped)
			case 16:
				args = append(args, m.row.LeaseExpires.Arg())
			case 17:
				args = append(args, m.row.FinishedAt.Arg())
			case 18:
				args = append(args, m.row.StoppedBy)
			case 19:
				args = append(args, m.row.StopReason)
			}
		}
		return run(st.SQL, append(args, q.bindPreds(b)...))
	}
}

// ExistsStep is the existence probe as a step: at most one row, when
// the query matches any. A write after it can act on whether it did.
func (q Query) ExistsStep() runtime.Step {
	return func(run func(string, []any) error) error {
		if err := q.Err(); err != nil {
			return err
		}
		if q.lock != 0 {
			return errExistsLocked
		}
		var buf [21]runtime.Tok
		st := existsStmtFor(q.preds(&buf))
		if st.Err != nil {
			return st.Err
		}
		b := binders.Get()
		defer putBinder(b)
		return run(st.SQL, q.bindPreds(b))
	}
}

