var afterCache = runtime.NewTreeCache()

const (
	stepOpen  = `WITH "_storm_step" AS (`
	stepClose = `) `
)

// afterStmtFor compiles one write after one step, once. The step's text
// is keyed by its hash and compared on a hit.
func afterStmtFor(step string, nStep int, k runtime.MaskKey, t Tally, preds []runtime.Tok) *runtime.Stmt {
	add, sub, ifNone, only := t.key()
	// The tally's columns are not m's: one assignment per column.
	k.Dirty &^= add | sub | ifNone
	k.Expr &^= add | sub | ifNone
	h := runtime.HashString(step)
	var key [34]runtime.Tok
	key[0], key[1], key[2] = runtime.Tok(h), runtime.Tok(h>>32), runtime.Tok(len(step))
	key[3], key[4] = runtime.Tok(k.Dirty), runtime.Tok(k.Dirty>>32)
	key[5], key[6] = runtime.Tok(k.Expr), runtime.Tok(k.Expr>>32)
	key[7], key[8] = runtime.Tok(add), runtime.Tok(add>>32)
	key[9], key[10] = runtime.Tok(sub), runtime.Tok(sub>>32)
	key[11], key[12] = runtime.Tok(ifNone), runtime.Tok(ifNone>>32)
	if only {
		key[12] |= 1 << 31 // nUpdatable < 64 leaves the top bit free
	}
	n := 13 + copy(key[13:], preds)
	if st := afterCache.Get(key[:n]); st != nil && len(st.SQL) > len(stepOpen)+len(step) && st.SQL[len(stepOpen):len(stepOpen)+len(step)] == step {
		return st
	}
	set := make([]runtime.Frag, 0, nUpdatable+1)
	for i := 0; i < nUpdatable; i++ {
		bit := uint64(1) << uint(i)
		switch {
		case ifNone&bit != 0:
			set = append(set, ifNoStepFrags[i])
		case add&bit != 0:
			set = append(set, stepAddFrags[i])
		case sub&bit != 0:
			set = append(set, stepSubFrags[i])
		case k.Expr&k.Dirty&bit != 0:
			set = append(set, addFrags[i])
		case k.Expr&bit != 0:
			set = append(set, exprFrags[i])
		case k.Dirty&bit != 0:
			set = append(set, setFrags[i])
		}
	}
	head := runtime.SpliceSectionsFrom(stepOpen+step+stepClose+updatePrefix, []runtime.Section{
		{Lead: "", Sep: ", ", Frags: set},
	}, "", nStep)
	if head.Err != nil {
		return head
	}
	var st *runtime.Stmt
	if only {
		st = runtime.SpliceTreeWhereFrom(head.SQL, `EXISTS (SELECT 1 FROM "_storm_step")`, preds, lowering, "", head.NArg)
	} else {
		st = runtime.SpliceTreeFrom(head.SQL, preds, lowering, "", head.NArg)
	}
	return afterCache.Put(key[:n], st)
}

// UpdateAllAfter writes m's assigned columns and t's tally to every row
// the query matches, after step, in ONE statement, and reports how many
// rows it wrote here:
//
//	var t Tally
//	t.Add…()         // … = … + the rows the step wrote
//	t.OnlyIfAny()    // and nothing at all when it wrote none
//	n, err := New().Where(…).UpdateAllAfter(ctx, ex, other.New().Where(…).UpdateAllStep(om), m, t)
//
// The step runs to completion whether or not anything here matches,
// and both see one snapshot. The query must have a predicate and no
// Limit, Offset or lock, as for UpdateAll.
func (q Query) UpdateAllAfter(ctx context.Context, ex runtime.Executor, step runtime.Step, m Mut, t Tally) (int64, error) {
	if err := q.writeAllErr(); err != nil {
		return 0, err
	}
	add, sub, ifNone, _ := t.key()
	tallied := add | sub | ifNone
	if (m.dirty|m.expr)&^tallied == 0 && tallied == 0 {
		return 0, runtime.ErrNothingAssigned
	}
	var written int64
	err := step(func(sql string, stepArgs []any) error {
		var buf [21]runtime.Tok
		st := afterStmtFor(sql, len(stepArgs), m.key(), t, q.preds(&buf))
		if st.Err != nil {
			return st.Err
		}
		b := binders.Get()
		defer putBinder(b)
		args := make([]any, 0, st.NArg)
		args = append(args, stepArgs...)
		for i := 0; i < nUpdatable; i++ {
			bit := uint64(1) << uint(i)
			switch {
			case ifNone&bit != 0:
				args = append(args, t.arg(i))
			case tallied&bit != 0, m.dirty&bit == 0:
			default:
				args = append(args, m.arg(i))
			}
		}
		args = append(args, q.bindPreds(b)...)
		n, err := ex.Exec(ctx, st.SQL, args)
		written = n
		return err
	})
	return written, err
}

func (m Mut) arg(i int) any {
	switch i {
	case 0:
		return m.row.UpdatedAt
	case 1:
		return m.row.ProjectID
	case 2:
		return m.row.OrganizationID
	case 3:
		return m.row.Kind
	case 4:
		return m.row.Reason
	case 5:
		return m.row.FilterStatus
	case 6:
		return m.row.FilterDefinitionID.Arg()
	case 7:
		return m.row.FilterBusinessKey
	case 8:
		return m.row.FilterNeedsAttention
	case 9:
		return m.row.RequestedBy
	case 10:
		return m.row.RequestedByID
	case 11:
		return m.row.Status
	case 12:
		return m.row.Total
	case 13:
		return m.row.Succeeded
	case 14:
		return m.row.Failed
	case 15:
		return m.row.Skipped
	case 16:
		return m.row.LeaseExpires.Arg()
	case 17:
		return m.row.FinishedAt.Arg()
	case 18:
		return m.row.StoppedBy
	case 19:
		return m.row.StopReason
	}
	return nil
}

